const msg = $input.item.json.message.text || '';
const userId = $input.item.json.message.from.id;
const chatId = $input.item.json.message.chat.id;
const ADMIN_PASS = '*FerFerreteriaNicoFabi2026';
const EDITOR_PASS = 'Precios2026';
const staticData = $getWorkflowStaticData('global');
if (!staticData.admins) staticData.admins = [];
if (!staticData.priceEditors) staticData.priceEditors = [];

if (msg.startsWith('/auth ')) {
  const provided = msg.slice(6).trim();
  if (provided === ADMIN_PASS) {
    if (!staticData.admins.includes(userId)) staticData.admins.push(userId);
    staticData.priceEditors = staticData.priceEditors.filter(function(id){ return id !== userId; });
    return [{ json: { chatId, userId, status: 'auth_ok', message: 'Acceso ADMIN concedido. Puedes usar todas las funciones.' } }];
  }
  if (provided === EDITOR_PASS) {
    if (!staticData.priceEditors.includes(userId)) staticData.priceEditors.push(userId);
    staticData.admins = staticData.admins.filter(function(id){ return id !== userId; });
    return [{ json: { chatId, userId, status: 'auth_ok', message: 'Acceso concedido. Puedes actualizar precios.' + String.fromCharCode(10) + String.fromCharCode(10) + 'Ejemplo: 50862 a 3500' } }];
  }
  return [{ json: { chatId, userId, status: 'auth_fail', message: 'Clave incorrecta.' } }];
}

if (staticData.admins.includes(userId)) {
  const item = Object.assign({}, $input.item.json, { status: 'continue', role: 'admin' });
  return [{ json: item }];
}
if (staticData.priceEditors.includes(userId)) {
  const item = Object.assign({}, $input.item.json, { status: 'continue', role: 'price_editor' });
  return [{ json: item }];
}

return [{ json: { chatId, userId, status: 'unauthorized', message: 'No tienes acceso.' + String.fromCharCode(10) + String.fromCharCode(10) + 'Envia: /auth CLAVE' } }];

const text = $input.first().json.message ? $input.first().json.message.text : ($input.first().json.message_text || '');
const prompt = "Eres asistente de ferreteria colombiana. Del mensaje extrae intencion y datos. Responde SOLO con JSON valido sin markdown ni texto adicional. Intenciones: change_price (cambiar precio, requiere codigo y precio entero sin puntos), query_price (consultar precio actual, requiere codigo), search_product (buscar por nombre o descripcion, requiere nombre), query_stock (ver inventario o stock, requiere codigo), historial (ver ultimos cambios de precio), unknown (no se entiende). Ejemplos: {\"intent\":\"change_price\",\"codigo\":\"50862\",\"precio\":3500} {\"intent\":\"query_price\",\"codigo\":\"50862\"} {\"intent\":\"search_product\",\"nombre\":\"bombillo led\"} {\"intent\":\"query_stock\",\"codigo\":\"50862\"} {\"intent\":\"historial\"} {\"intent\":\"unknown\"}. Mensaje del usuario: ";
return [{ json: {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 150,
  messages: [{ role: 'user', content: prompt + text }]
} }];

const text = ($input.first().json.content && $input.first().json.content[0] ? $input.first().json.content[0].text : $input.first().json.text || '').trim();
try {
  const clean = text.replace(/```json|```/g, '').trim();
  return [{ json: JSON.parse(clean) }];
} catch(e) {
  return [{ json: { error: 'parse: ' + text } }];
}

const parsed = $('Parsear JSON').first().json;
const token = $input.first().json.access_token;
let searchUrl;
if (parsed.codigo) {
  searchUrl = 'https://api.siigo.com/v1/products?code=' + parsed.codigo;
} else if (parsed.nombre) {
  searchUrl = 'https://api.siigo.com/v1/products?name=' + encodeURIComponent(parsed.nombre);
}
return [{ json: { token, searchUrl, searchType: parsed.codigo ? 'codigo' : 'nombre' } }];

const product = $('Siigo Buscar').first().json.results[0];
const token = $('Siigo Auth').first().json.access_token;
const newPrice = Number($('Parsear JSON').first().json.precio);
const total = $('Siigo Buscar').first().json.pagination.total_results;
const prices = product.prices.map(function(g) {
  return Object.assign({}, g, { price_list: g.price_list.map(function(p, idx) {
    return idx === 0 ? Object.assign({}, p, { value: newPrice }) : p;
  })});
});
const staticData = $getWorkflowStaticData('global');
if (!staticData.history) staticData.history = [];
staticData.history.push({ fecha: new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota' }), codigo: product.code, nombre: product.name, precio: newPrice });
if (staticData.history.length > 50) staticData.history = staticData.history.slice(-50);
return [{ json: { token, productId: product.id, productCode: product.code, productName: product.name, newPrice, total, updateBody: { code: product.code, name: product.name, account_group: product.account_group.id, type: product.type, stock_control: product.stock_control, active: product.active, tax_classification: product.tax_classification, tax_included: product.tax_included, taxes: product.taxes, prices: prices, unit: product.unit } } }];

const data = $input.first().json;
const chatId = $('Telegram Trigger').first().json.message.chat.id;
if (!data.results || data.results.length === 0) {
  return [{ json: { chatId, found: false, codigo: $('Parsear JSON').first().json.codigo } }];
}
const NL = String.fromCharCode(10);
const p = data.results[0];
const priceVal = p.prices && p.prices[0] && p.prices[0].price_list && p.prices[0].price_list[0] ? p.prices[0].price_list[0].value : 0;
return [{ json: { chatId, found: true, name: p.name, code: p.code, precio: priceVal } }];

const data = $input.first().json;
const chatId = $('Telegram Trigger').first().json.message.chat.id;
if (!data.results || data.results.length === 0) {
  return [{ json: { chatId, message: 'No encontre productos con ese nombre.' } }];
}
const NL = String.fromCharCode(10);
const lines = data.results.slice(0, 10).map(function(p) {
  const priceVal = p.prices && p.prices[0] && p.prices[0].price_list && p.prices[0].price_list[0] ? p.prices[0].price_list[0].value : 0;
  return p.code + ' - ' + p.name + ' ($' + priceVal + ')';
});
const total = data.pagination ? data.pagination.total_results : data.results.length;
return [{ json: { chatId, message: 'Resultados (' + total + '):' + NL + NL + lines.join(NL) } }];

const data = $input.first().json;
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const codigo = $('Parsear JSON').first().json.codigo;
if (!data.results || data.results.length === 0) {
  return [{ json: { chatId, message: 'Producto no encontrado. Codigo: ' + codigo } }];
}
const NL = String.fromCharCode(10);
const p = data.results[0];
const stock = p.available_quantity !== undefined ? p.available_quantity : (p.stock_control ? 'Con control de inventario' : 'Sin control de inventario');
return [{ json: { chatId, message: 'Inventario' + NL + NL + 'Producto: ' + p.name + NL + 'Codigo: ' + p.code + NL + 'Stock: ' + stock } }];

const staticData = $getWorkflowStaticData('global');
const chatId = $input.first().json.message.chat.id;
const history = staticData.history || [];
if (history.length === 0) {
  return [{ json: { chatId, message: 'No hay cambios registrados aun.' } }];
}
const NL = String.fromCharCode(10);
const lines = history.slice(-10).reverse().map(function(h) {
  return h.fecha + NL + h.codigo + ' - ' + h.nombre + NL + 'Precio: $' + h.precio;
});
return [{ json: { chatId, message: 'Ultimos cambios:' + NL + NL + lines.join(NL + NL) } }];

const role = $('Limpiar Clave').first().json.role || 'admin';
const intent = $json.intent || 'unknown';
const chatId = $('Telegram Trigger').first().json.message.chat.id;

if (role === 'price_editor' && intent !== 'change_price') {
  const NL = String.fromCharCode(10);
  return [{ json: { chatId, _blocked: true, message: 'No tienes permiso para esta accion.' + NL + 'Solo puedes actualizar precios.' + NL + NL + 'Ejemplo: 50862 a 3500' } }];
}

return [{ json: Object.assign({}, $input.first().json, { _blocked: false }) }];

